// Independent root audit against the frozen evaluation checkpoint.
#define main frozen_reference_main
#include "/work/ceres_ref-source-1d6424f.cc"
#undef main
#include <ceres/product_manifold.h>

int main() {
  using namespace ceres_rig_reference;
  using Row27 = Eigen::Matrix<double, 2, 7, Eigen::RowMajor>;
  using Row23 = Eigen::Matrix<double, 2, 3, Eigen::RowMajor>;
  using Row76 = Eigen::Matrix<double, 7, 6, Eigen::RowMajor>;
  Eigen::Quaterniond q(.91,.17,-.23,.29), sensor(.98,-.09,.14,.03);
  q.normalize(); sensor.normalize();
  double pose[7]={q.w(),q.x(),q.y(),q.z(),.3,.2,.5};
  double point[3]={.4,-.8,4.2};
  Camera camera; camera.intrinsics={410.,405.,320.,240.};
  Observation obs; obs.xy=Eigen::Vector2d(123.,234.);
  obs.sensor_from_rig_rotation=sensor;
  obs.sensor_from_rig_translation=Eigen::Vector3d(-.064,.02,.01);
  auto cost=MakeRigReprojectionCost(camera,obs);
  const double* parameters[]={pose,point};
  double residual[2];
  Row27 jp; Row23 jx;
  double* jacobians[]={jp.data(),jx.data()};
  if (!cost->Evaluate(parameters,residual,jacobians)) return 2;
  // Deliberately independent Eigen projection, not the factor's TransformPoint.
  const auto project=[&](const double* p,const double* x)->Eigen::Vector2d {
    Eigen::Quaterniond r(p[0],p[1],p[2],p[3]); r.normalize();
    Eigen::Vector3d y=sensor.toRotationMatrix()*
      (r.toRotationMatrix()*Eigen::Map<const Eigen::Vector3d>(x)+
       Eigen::Map<const Eigen::Vector3d>(p+4))+obs.sensor_from_rig_translation;
    if (!(y.z()>0)) throw std::runtime_error("bad independent depth");
    return Eigen::Vector2d(410.*y.x()/y.z()+320.-123.,
                          405.*y.y()/y.z()+240.-234.);
  };
  constexpr double eps=1e-7;
  Row27 np; Row23 nx;
  for(int k=0;k<7;++k) {
    std::array<double,7> a,b; std::copy(pose,pose+7,a.begin()); b=a;
    a[k]+=eps; b[k]-=eps;
    np.col(k)=(project(a.data(),point)-project(b.data(),point))/(2*eps);
  }
  for(int k=0;k<3;++k) {
    std::array<double,3> a,b; std::copy(point,point+3,a.begin()); b=a;
    a[k]+=eps; b[k]-=eps;
    nx.col(k)=(project(pose,a.data())-project(pose,b.data()))/(2*eps);
  }
  ceres::ProductManifold<ceres::QuaternionManifold,
                        ceres::EuclideanManifold<3>> manifold;
  Row76 plus;
  if (!manifold.PlusJacobian(pose,plus.data())) return 3;
  Eigen::Matrix<double,2,6> tangent=jp*plus, nt;
  for(int k=0;k<6;++k) {
    double d[6]={},a[7],b[7]; d[k]=eps;
    if (!manifold.Plus(pose,d,a)) return 4;
    d[k]=-eps;
    if (!manifold.Plus(pose,d,b)) return 5;
    nt.col(k)=(project(a,point)-project(b,point))/(2*eps);
  }
  Eigen::Vector3d u=q.toRotationMatrix()*Eigen::Map<const Eigen::Vector3d>(point);
  Eigen::Vector3d y=sensor.toRotationMatrix()*(u+Eigen::Map<const Eigen::Vector3d>(pose+4))+
                    obs.sensor_from_rig_translation;
  Eigen::Matrix<double,2,3> projection;
  projection << 410./y.z(),0.,-410.*y.x()/(y.z()*y.z()),
                0.,405./y.z(),-405.*y.y()/(y.z()*y.z());
  Eigen::Matrix3d cross;
  cross << 0.,-u.z(),u.y(),u.z(),0.,-u.x(),-u.y(),u.x(),0.;
  Eigen::Matrix<double,2,6> analytic;
  analytic.leftCols<3>()=projection*sensor.toRotationMatrix()*(-2.*cross);
  analytic.rightCols<3>()=projection*sensor.toRotationMatrix();
  const double ambient_error=(jp-np).cwiseAbs().maxCoeff();
  const double point_error=(jx-nx).cwiseAbs().maxCoeff();
  const double tangent_error=(tangent-nt).cwiseAbs().maxCoeff();
  const double analytic_error=(tangent-analytic).cwiseAbs().maxCoeff();
  const double point_analytic_error=
    (jx-projection*sensor.toRotationMatrix()*q.toRotationMatrix()).cwiseAbs().maxCoeff();
  if (ambient_error>1e-5 || point_error>1e-5 || tangent_error>1e-5 ||
      analytic_error>1e-9 || point_analytic_error>1e-9) return 6;
  std::cout<<std::setprecision(17)
    <<"root_derivative_audit=PASS ambient_fd_max="<<ambient_error
    <<" point_fd_max="<<point_error<<" tangent_fd_max="<<tangent_error
    <<" tangent_analytic_max="<<analytic_error
    <<" point_analytic_max="<<point_analytic_error<<"\n";
}
